import { privateJson,logout } from './session.js';
import { mountCoaching } from './coaching.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#logout').addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await logout();}catch(e){$('#account-status').textContent=e.message;event.currentTarget.disabled=false;}});
async function load(){const p=await privateJson('/api/private?route=profile');$('#member-name').textContent=p.user.displayName;$('#member-email').textContent=p.user.email;$('#avatar').textContent=p.user.displayName.slice(0,1).toUpperCase();$('#garmin-status').textContent=p.garmin.configured?'Connected':'Not connected';$('#garmin-description').textContent=p.garmin.configured?'Your connection is ready. Pull your recent runs into your private record.':'A Garmin connection has not been set up for this account. You can import original FIT recordings below.';$('#sync-garmin').hidden=!p.garmin.configured;$('#submissions').innerHTML=p.submissions.length?p.submissions.map(s=>`<div class="ac-submission"><div><strong>${esc(s.original_name)}</strong><span>${s.provider==='strava'?'Strava':'Nike Run Club'} · ${new Date(s.created_at).toLocaleDateString('en-AU')}</span></div><span class="ac-badge">${esc(s.status.replaceAll('_',' '))}</span></div>`).join(''):'<p>No screenshots waiting for review.</p>';}
$('#sync-garmin').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;$('#fit-status').textContent='Syncing your Garmin recordings…';try{const r=await privateJson('/api/garmin/sync',{method:'POST'});$('#fit-status').textContent=`${r.imported} added · ${r.updated} updated · ${r.unchanged} unchanged. Open Training to explore.`;}catch(e){$('#fit-status').textContent=e.message;}finally{button.disabled=false;}});
$('#fit-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const out=$('#fit-status');if(file.size>3.5*1024*1024){out.textContent='Choose a FIT file smaller than 3.5 MB.';return;}event.target.disabled=true;out.textContent='Saving your recording…';try{const r=await privateJson('/api/import',{method:'POST',body:file});out.innerHTML=`${r.duplicate?'Already in your record.':'Recording saved.'} <a href="/app.html?activity=${encodeURIComponent(r.activity.id)}">Open session ↗</a>`;}catch(e){out.textContent=e.message;}finally{event.target.disabled=false;}});
$('#screenshots').addEventListener('change',event=>{$('#file-selection').textContent=event.target.files.length+' screenshots selected';});
$('#screenshot-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,files=[...$('#screenshots').files],button=form.querySelector('button'),out=$('#screenshot-status');if(!files.length||files.length>20||files.some(f=>f.size>3.5*1024*1024)){out.textContent='Choose up to 20 JPG or PNG files, each smaller than 3.5 MB.';return;}button.disabled=true;const batch=crypto.randomUUID();let done=0;try{for(const file of files){out.textContent=`Saving screenshot ${done+1} of ${files.length}…`;await privateJson('/api/private?route=screenshots',{method:'POST',headers:{'x-source-provider':$('#provider').value,'x-import-batch':batch,'x-original-name':encodeURIComponent(file.name)},body:file});done++;}out.textContent=`${done} screenshots saved privately for review. They will appear as runs after their dates and figures are checked.`;form.reset();$('#file-selection').textContent='JPG or PNG · up to 20 images · 3.5 MB each';await load();}catch(e){out.textContent=`${done} saved. ${e.message} You can retry; identical images will not duplicate.`;}finally{button.disabled=false;}});
$('#password-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,out=$('#password-status'),button=form.querySelector('button');if($('#new-password').value!==$('#confirm-password').value){out.textContent='The passwords do not match.';$('#confirm-password').focus();return;}button.disabled=true;try{await privateJson('/api/private?route=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#new-password').value})});form.reset();out.textContent='Password updated.';}catch(e){out.textContent=e.message;}finally{button.disabled=false;}});
try{await load();const coach=document.createElement('section');coach.setAttribute('aria-label','AI preferences');$('.ac-intro').after(coach);await mountCoaching(coach,{settings:true});if(location.hash==='#ai-settings')coach.scrollIntoView();}catch(e){$('#account-status').textContent=e.message;}
